class Solution {
    public boolean areOccurrencesEqual(String s){
        int[] frequency=new int[26];
        for(char letter:s.toCharArray())frequency[letter-'a']++;
        int baseline=0;
        for(int value:frequency)if(value>0){
            if(baseline==0)baseline=value;
            else if(value!=baseline)return false;
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun areOccurrencesEqual(s:String):Boolean{
        val frequency=IntArray(26);
        for(letter in s)frequency[letter-'a']++;
        val values=frequency.filter{
            it>0
        };
        return values.all{
            it==values[0]
        }
    }
}

